<script setup lang="ts">
import {ref,onMounted} from 'vue';import axios from 'axios';
const places=ref<{id:number;name:string;description:string}[]>([]),selected=ref<number|null>(null),comments=ref<{id:number;username:string;content:string;createdAt:string}[]>([]),content=ref(''),error=ref(''),busy=ref(false),me=ref(''),more=ref(false);
let loadSequence=0;
async function load(id:number,append=false){const sequence=++loadSequence;selected.value=id;error.value='';try{const {data}=await axios.get('/api/campus/places/'+id+'/comments',{params:{before:append?comments.value.at(-1)?.id:0}});if(sequence!==loadSequence)return;comments.value=append?[...comments.value,...data]:data;more.value=data.length===20;}catch{error.value='讨论加载失败，请重新选择地点。';}}
async function headers(){return {'X-XSRF-TOKEN':(await axios.get('/api/auth/csrf')).data.token};}
async function send(){if(!selected.value||!content.value.trim())return;busy.value=true;try{await axios.post('/api/campus/places/'+selected.value+'/comments',{content:content.value},{headers:await headers()});content.value='';await load(selected.value);}catch{error.value='发送失败，请稍后重试';}finally{busy.value=false;}}
async function remove(id:number){try{await axios.delete('/api/campus/places/'+selected.value+'/comments/'+id,{headers:await headers()});await load(selected.value!);}catch{error.value='删除失败';}}
onMounted(async()=>{try{me.value=(await axios.get('/api/auth/me')).data.username;places.value=(await axios.get('/api/campus/places')).data;if(places.value[0])await load(places.value[0].id);}catch{error.value='地点加载失败，请刷新重试';}});
</script>
<template><section class="campus"><p class="kicker">SDU / CAMPUS STORIES</p><h1>校园地图与地点交流</h1><p>熟悉的校园，也有新的故事。</p><a class="map-link" href="https://map.qq.com/" target="_blank" rel="noopener noreferrer">打开腾讯地图，搜索山东大学青岛校区 ↗</a><p class="hint">站内地图尚未接入；地点讨论已开放。</p><div class="campus-layout"><aside><button v-for="place in places" :key="place.id" :class="{active:selected===place.id}" @click="load(place.id)">{{place.name}}<small>{{place.description}}</small></button></aside><main><h2>{{places.find(p=>p.id===selected)?.name}}</h2><p role="alert">{{error}}</p><form @submit.prevent="send"><label>分享校园日常<textarea v-model="content" required maxlength="1000" placeholder="说说这里的故事…"></textarea></label><button :disabled="busy||!content.trim()">{{busy?'发送中…':'发布留言'}}</button></form><p v-if="!comments.length">还没有留言，来分享第一条校园日常。</p><article v-for="comment in comments" :key="comment.id"><strong>{{comment.username}}</strong><time>{{comment.createdAt}}</time><p>{{comment.content}}</p><button v-if="comment.username===me" @click="remove(comment.id)">删除我的留言</button></article><button v-if="more" @click="load(selected!,true)">加载更早留言</button></main></div></section></template>
<style scoped>.campus{background:#f6f4ee;color:#293d3b;padding:40px 6%;flex:1}.kicker{font-size:10px;letter-spacing:3px;color:#92724b}h1{font-size:34px;margin:20px 0}.map-link{display:inline-block;color:#8d573b;margin-top:15px}.hint{font-size:12px;color:#8d806b}.campus-layout{display:grid;grid-template-columns:260px 1fr;gap:30px;margin-top:30px}aside button{display:block;width:100%;margin-bottom:12px;text-align:left;padding:22px;background:white;color:#304b49;border:1px solid #dcded4;border-radius:8px}small{display:block;font-size:10px;color:#869184;margin-top:10px}aside .active{border-color:#9c794a;background:#f6ebce}main{background:white;padding:28px;border-radius:10px}textarea{display:block;width:100%;min-height:100px;padding:14px;border:1px solid #d8dcd3;border-radius:5px;margin:12px 0;font:inherit}button{background:#304b49;color:white;padding:10px 20px;border:0;border-radius:5px}button:disabled{opacity:.5}article{border-top:1px solid #e7e7df;margin-top:24px;padding-top:20px}article p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8}time{font-size:11px;color:#88958a;margin-left:20px}article button{background:none;color:#90634c;font-size:11px;padding:0}@media(max-width:750px){.campus-layout{grid-template-columns:1fr}aside{display:flex;gap:10px;overflow:auto}aside button{min-width:190px}main{padding:20px}}
</style>
